"""Execute an inspectable companion for the existing-data revenue extension."""
from pathlib import Path
import sys

import nbformat as nbf
from nbclient import NotebookClient
from jupyter_client import KernelManager
from jupyter_client.kernelspec import KernelSpec

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "outputs/regional_revenue_candidate_2026-09-30"
nb = nbf.v4.new_notebook(cells=[
    nbf.v4.new_markdown_cell("# Regional revenue coverage audit\n\n## tl;dr\n78 regions have six revenue categories across Q1 and first-half 2023–2026: 3,744 observations. All 624 actual revenue totals reconcile to tax/non-tax plus non-repayable receipts. The published revenue plan components do not reconcile in 23 region-periods; affected execution percentages are withheld. This is a review candidate."),
    nbf.v4.new_markdown_cell("## Context & Methods\nAmounts are nominal RUB and actuals are YTD. Treasury classification 202 identifies transfers from other budgets; 200 includes broader non-repayable receipts and repayments. The parser chooses columns by the consolidated regional header and selects administrator-000 parent rows. Audit scripts: `build_regional_revenue_candidate.py` and `build_exchange_package.py`.\n\n### Key assumptions\nRegional plus municipal budgets exclude territorial health-insurance funds. Snapshot plans do not identify original budgets or subsequent amendments. Quarter flows require genuine adjacent same-year snapshots. No national aggregation, sanctions attribution, debt-stock inference or CPI adjustment is made."),
    nbf.v4.new_code_cell("from pathlib import Path\nimport sys\nimport json\nimport pandas as pd\nfrom IPython.display import display\nroot = next(p for p in [Path.cwd(), *Path.cwd().parents] if (p/'src/macro_rus').is_dir())\nsys.path.insert(0, str(root/'src'))\nfrom macro_rus.revenue_view import load_revenue_candidate, revenue_indicators, OWN, NON_REPAYABLE, TRANSFERS\nout = root/'outputs/regional_revenue_candidate_2026-09-30'\ntables, manifest = load_revenue_candidate(out)\nbudget = tables['budget_execution']\nindicators = revenue_indicators(budget)\nprint('Regions:', budget.region_id.nunique(), '| Observations:', len(budget), '| Region-periods:', manifest['region_periods'])"),
    nbf.v4.new_markdown_cell("## Data\n`lineage.csv` identifies the raw archive hash, HTML member and selected row/columns. `sources.csv` supplies official source pages; unknown publication and retrieval times remain blank. Prior pilot regression controls cover 80 retained revenue observations."),
    nbf.v4.new_code_cell("assert len(budget) == 3744\nassert budget.region_id.nunique() == 78\nassert not budget.duplicated(['region_id','period','revenue_code']).any()\nassert manifest['pilot_parity_rows'] == 80\nassert not set(budget.region_id) & {'FNS-72','FNS-91'}\nchecks = pd.read_csv(out/'accounting_checks.csv')\nactual_checks = checks[checks.blocking]\nassert len(actual_checks) == 624 and actual_checks.passed.all()\nplan_warnings = checks[(~checks.blocking) & (~checks.passed)]\nassert len(plan_warnings) == 23\ndisplay(plan_warnings[['region_id','period','gap_rub']].head(8))"),
    nbf.v4.new_markdown_cell("## Results\nThe table is a bounded source sample for Tatarstan, first-half 2026. The tax categories are nested detail, not additional components of total revenue."),
    nbf.v4.new_code_cell("selected = indicators[(indicators.region_id == 'FNS-16') & (indicators.period == pd.Timestamp('2026-06-30'))].copy()\nassert len(selected) == 6\ndisplay(selected[['revenue_name_en','actual_ytd_rub','growth_yoy_pct','quarter_flow_rub']].rename(columns={'revenue_name_en':'Revenue','actual_ytd_rub':'Actual YTD (RUB)','growth_yoy_pct':'Same-period YoY (%)','quarter_flow_rub':'Q2 flow (RUB)'}).round(2))\nvalues = selected.set_index('revenue_code').actual_ytd_rub\nassert abs(values['TOTAL_REVENUE'] - values[OWN] - values[NON_REPAYABLE]) <= .02\nprint('Transfers from other budgets / total revenue:', round(values[TRANSFERS]/values['TOTAL_REVENUE']*100,2), '%')"),
    nbf.v4.new_code_cell("assert indicators.quarter_flow_rub.notna().all()\nq1 = indicators[indicators.period.dt.month == 3].copy()\nq2 = indicators[indicators.period.dt.month == 6].copy()\nq1['year'] = q1.period.dt.year\nq2['year'] = q2.period.dt.year\njoined = q2.merge(q1, on=['region_id','year','revenue_code'], validate='one_to_one', suffixes=('_q2','_q1'))\nassert len(joined) == 1872\nassert (joined.quarter_flow_rub_q2 + joined.quarter_flow_rub_q1 - joined.actual_ytd_rub_q2).abs().le(.02).all()\nassert indicators.loc[~indicators.plan_components_reconciled, 'snapshot_execution_pct'].isna().all()\nassert indicators.loc[indicators.period.dt.year.eq(2023), 'growth_yoy_pct'].isna().all()\nprint('Adjacent-quarter flow reconciliations:',len(joined),'| Missing 2023 YoY retained:',int(indicators.loc[indicators.period.dt.year.eq(2023),'growth_yoy_pct'].isna().sum()))"),
    nbf.v4.new_markdown_cell("## Takeaways\nActual fiscal revenues can be compared across the same reporting periods. Transfer dependence uses the 202 intergovernmental category, not all non-repayable receipts. Plan discrepancies remain visible and affected percentages are suppressed. Full-year fiscal history, historical FNS schemas, inflation, population and debt remain future inputs. Detailed PIT–Treasury reconciliation still needs aligned scope and missing-sector resolution. This companion uses bounded diagnostic tables; economic charts are available in Streamlit."),
])
nb.metadata["kernelspec"] = {"name": "python3", "display_name": "Python 3", "language": "python"}
nbf.validate(nb)
km = KernelManager()
km._kernel_spec = KernelSpec(argv=[sys.executable, "-m", "ipykernel_launcher", "-f", "{connection_file}"], display_name="Python 3", language="python")
NotebookClient(nb, km=km, timeout=90, resources={"metadata": {"path": str(ROOT)}}).execute()
nbf.write(nb, OUT / "revenue_audit.ipynb")
print("Executed", OUT / "revenue_audit.ipynb")
